 private static void requireControl(Selection s,Object value){if(value instanceof ReligionModels.CreationContext c){require(c.frame().availability().available()&&Boolean.TRUE.equals(c.windowPresent())&&Boolean.TRUE.equals(c.rootPresent())&&Boolean.TRUE.equals(c.playerFaithMatches())&&c.selectionAvailable(),"actual later creation window model/selection incomplete");require(s.operation()==Operation.OPEN_CREATION||s.operation()==Operation.TYPE&&Objects.equals(c.selectedType(),s.type().orElseThrow())||s.operation()==Operation.BARONY&&Objects.equals(c.selectedBarony(),s.subject()),"actual later selection differs");}else if(value instanceof ReligionHolyState.State state){var window=state.window().orElseThrow();require(state.frame().availability().available()&&window.availability().available()&&Boolean.TRUE.equals(window.present().orElse(null))&&Boolean.TRUE.equals(window.rootPresent().orElse(null))&&window.holySiteId().equals(Optional.of(s.subject())),"actual later Holy window model differs");}else if(value instanceof ReligionModels.DecisionDetail detail){require(detail.frame().availability().available()&&detail.detailContextVerified()&&detail.holySiteId().equals(s.subject())&&detail.action()==s.decision().orElse(ReligionModels.Decision.ADOPT),"actual later parameterized decision detail differs");}else throw new IllegalArgumentException("unregistered Holy postread model");}
 private static void requireSame(ActionCommand before,Complete current){require(current.identity().game().equals(before.before().game())&&current.identity().frame().episodeRunId().equals(before.before().frame().episodeRunId())&&current.identity().frame().identity().player().equals(before.before().frame().identity().player())&&current.identity().frame().identity().dateRaw().equals(before.before().frame().identity().dateRaw())&&current.identity().frame().identity().nativeRevision().equals(before.before().frame().identity().nativeRevision())&&current.identity().frame().snapshotId().equals(before.before().frame().snapshotId())&&current.source().equals(before.source())&&current.sessionId().equals(before.sessionId()),"Holy control observation crossed actual Game/episode/player/source");}
