 private static Data data(ActionCommand command){ObjectNode fields=(ObjectNode)OpportunityJson.toNode(command.arguments());ObjectNode meta=StrictJson.object(fields.get(META),Set.of("schema","original_method","scope_episode","connection_generation","native_revision","date_raw","actor_id","once_key","original_once_manifest"));require(meta.path("schema").asText().equals("xar.java.holy-original-command/v1"),"Holy canonical metadata schema differs");String method=StrictJson.text(meta.get("original_method"));require(METHODS.contains(method)&&!method.startsWith("ck3_query_"),"Holy original action name differs");Frame frame=new Frame(PublicUnsigned64.parse(meta.get("native_revision"),PublicUnsigned64.Minimum.ONE,PublicUnsigned64.NumericInput.DECIMAL_ONLY),integer(meta,"date_raw"),integer(meta,"actor_id"),PublicUnsigned64.parse(meta.get("connection_generation"),PublicUnsigned64.Minimum.ONE,PublicUnsigned64.NumericInput.DECIMAL_ONLY));ObjectNode wire=fields.deepCopy();wire.remove(META);Selection selection=ReligionHolyUi.selection(wire);require(wire.equals(canonicalFields(selection,frame)),"Holy canonical fields include non-native aliases");JsonNode old=meta.get("original_once_manifest");require((selection.operation()==Operation.CREATE)==!old.isNull(),"Holy original once manifest belongs only to final creation");return new Data(selection,frame,method,StrictJson.text(meta.get("scope_episode")),StrictJson.text(meta.get("once_key")),old.isNull()?Optional.empty():Optional.of(ExactRef.fromJson(old)));}
 private static void requireOriginalMethod(Data data,ActionCommand command){ObjectNode original=StrictJson.object();for(Field field:ReligionCodec.method(data.originalMethod()).fields())switch(field){case EXPECTED_REVISION->original.put(field.wire(),command.before().frame().revision().toString());case HOLY_SITE_ID,BARONY_TITLE_ID->original.put(field.wire(),data.selection().subject());case TYPE_KEY->original.put(field.wire(),data.selection().type().orElseThrow());case EXPECTED_PREVIEW_IDENTITY_SHA256->original.put(field.wire(),data.selection().preview().orElseThrow());case ACTION->original.put(field.wire(),data.selection().decision().orElseThrow().wire());default->throw new IllegalArgumentException("unexpected field on original Holy action");}require(ReligionHolyUi.selection(ReligionCodec.decode(data.originalMethod(),ReligionCodec.raw(original))).equals(data.selection()),"retained Holy method/typed selector contract differs");}
