 public static String onceKey(String machine,String episode,Selection s,Frame frame){ObjectNode n=StrictJson.object().put("machine_id",machine).put("game_version",ReligionModels.Build.CROZIER4.version()).put("executable_sha256",ReligionModels.Build.CROZIER4.sha256()).put("date_raw",frame.date()).put("played_character_id",frame.actor()).put("operation",s.operation().wire()).put("window_kind",s.operation().window()).put("subject_id",s.subject());n.putObject("scope").put("kind","one_life_episode").put("episode_run_id",episode);if(s.preview().isPresent())n.put("expected_preview_identity_sha256",s.preview().orElseThrow());if(s.operation()==Operation.CONFIRM)n.put("holy_site_action",s.decision().orElse(ReligionModels.Decision.ADOPT).wire());else s.decision().ifPresent(v->n.put("holy_site_action",v.wire()));return ActionCodec.sha256(pythonAscii(n).getBytes(StandardCharsets.UTF_8));}
 private static String pythonAscii(JsonNode n){if(n.isObject()){var keys=new ArrayList<String>();n.fieldNames().forEachRemaining(keys::add);keys.sort(Comparator.naturalOrder());return "{"+keys.stream().map(k->pythonAscii(com.fasterxml.jackson.databind.node.TextNode.valueOf(k))+":"+pythonAscii(n.get(k))).collect(java.util.stream.Collectors.joining(","))+"}";}if(n.isTextual()){String value=n.textValue();var out=new StringBuilder("\"");for(int i=0;i<value.length();i++){char c=value.charAt(i);switch(c){case '"'->out.append("\\\"");case '\\'->out.append("\\\\");case '\b'->out.append("\\b");case '\f'->out.append("\\f");case '\n'->out.append("\\n");case '\r'->out.append("\\r");case '\t'->out.append("\\t");default->{if(c<32||c>=127)out.append(String.format(java.util.Locale.ROOT,"\\u%04x",(int)c));else out.append(c);}}}return out.append('"').toString();}require(n.isIntegralNumber()||n.isBoolean()||n.isNull(),"original once identity JSON domain");return n.toString();}
 private static ExactRef source(Path path)throws IOException{var observed=SharedSourceFiles.observe(path);SharedSourceFiles.assertUnchanged(observed);var ref=observed.source();return new ExactRef(ref.path(),ref.bytes(),ref.sha256());}
